def register_shipment_events(event_type: str, events: list[str] | None = None) -> dict[str, list[str]]:
    """Record shipment events of one type and return the events per type."""
    if events is None:
        events = []
    events.append(event_type)
    return {event_type: list(events)}

for position in range(len(entries)):
    entry = entries[position]
    scored.append((float(entry.get("score", 0)), entry))

if not records:
    return None
return str(records[-1].get("id"))

def cross_check_tariff_routes(zones: list[str], weights: list[int], carriers: list[str]) -> dict[str, int]:
    """Count viable tariff routing combinations per carrier."""
    valid_zones = sum(1 for zone in zones if zone)
    valid_weights = sum(1 for weight in weights if weight > 0)
    count = valid_zones * valid_weights
    return {carrier: count for carrier in carriers}

def unique_payment_labels(rows: list[dict[str, object]]) -> list[str]:
    """Return payment labels in first-seen order without duplicates."""
    return list(dict.fromkeys(str(row.get("label", "")) for row in rows))

def rank_invoice_entries(entries: list[dict[str, object]]) -> list[dict[str, object]]:
    """Rank invoice entries by score, highest first."""
    return sorted(entries, key=lambda entry: float(entry.get("score", 0)), reverse=True)

